return $input.all().map(item => {
  const keys = Object.keys(item.json);
  const dateKey  = keys.find(k => k.toLowerCase().replace(/_/g,'').includes('nextfollowup'));
  const stageKey = keys.find(k => k.trim() === 'Stage');
  const rawDate  = dateKey  ? item.json[dateKey]  : null;
  const rawStage = stageKey ? item.json[stageKey] : null;
  const rawReply = item.json['Has_Replied'];
  const rawUnsub = item.json['Unsubscribed'];
  item.json.Next_Followup_At_ts = rawDate ? new Date(rawDate).getTime() : 0;
  item.json.Now_ts              = Date.now();
  item.json.Stage_Int           = parseInt(rawStage, 10) || 0;
  item.json.Has_Replied_Bool    = String(rawReply).trim().toUpperCase() === 'TRUE';
  item.json.Unsubscribed_Bool   = String(rawUnsub).trim().toUpperCase() === 'TRUE';
  item.json.SMS_Sent_Day1_Bool  = String(item.json['SMS_Sent_Day1'] || '').trim().toUpperCase() === 'TRUE';
  item.json.SMS_Sent_Day4_Bool  = String(item.json['SMS_Sent_Day4'] || '').trim().toUpperCase() === 'TRUE';
  item.json.SMS_Consent_Bool    = String(item.json['SMS_Consent'] || '').trim().toUpperCase() === 'TRUE';
  // Phase 3: Handle lead_source and service_of_interest with fallbacks
  item.json.lead_source          = item.json['lead_source'] || item.json['Lead_Source'] || 'Unknown';
  item.json.service_of_interest   = item.json['service_of_interest'] || item.json['Service_Of_Interest'] || 'General Inquiry';
  return item;
});

const raw = $input.first().json.text || $input.first().json.content || '';
let cleaned = raw.trim();

// Strip markdown code fences if model added them
cleaned = cleaned.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Fallback if LLM returns malformed JSON
  parsed = {
    subject: "Following up with you",
    body: "<p>Hi, just wanted to reach out and see if we can connect. Feel free to reply anytime.</p>"
  };
}

return [{ json: { subject: parsed.subject, body: parsed.body } }];

parameters.text:
=`You are writing a follow-up email on behalf of  YOUR NAME/company.

Lead details:
- Name: ${ $('Route by Stage').item.json['Name'] }
- First name: ${ $('Route by Stage').item.json['First_Name'] }
- Lead Source: {{ $json.lead_source }}
- Service Interested In: {{ $json.service_of_interest }}

This lead received a welcome email 3 days ago and has not replied.

Instructions:
- Write a short, low-pressure check-in email (2-4 sentences)
- Tone: casual and helpful, not pushy
- Use the lead's specific service of interest to mention a benefit related to that service in the email
- Offer a specific next step (15-min call, quick question, etc.)
- Append this exact footer as a new paragraph: "Reply STOP to unsubscribe."
- Return ONLY this JSON, nothing else:
{"subject": "...", "body": "..."}
The body should be plain HTML using only <p> tags.`

